// Each pack bundles its skills in its own tree (<pack>/skills/<name>/ — the
// one shape, #385).
function makeCorpus({ packs }, root = mkdtempSync(join(tmpdir(), 'claudinite-corpus-'))) {
  mkdirSync(join(root, 'packs'), { recursive: true });
  // The WHOLE loader directory, never an enumerated subset: the registry pulls in
  // its siblings (the manifest spec, the renamed-pack map) and a fixture listing
  // files by hand goes quietly fail-soft the day one is added — mounting nothing
  // and reporting success.
  cpSync(join(REPO_ROOT, 'engine', 'pack_loader'), join(root, 'engine', 'pack_loader'), { recursive: true });
  // pack-schema validates a version against the engine's version module, which sits
  // beside pack_loader in the real tree.
  cpSync(join(REPO_ROOT, 'engine', 'version.mjs'), join(root, 'engine', 'version.mjs'));
  for (const [id, def] of Object.entries(packs)) {
    const { skills = [], ...manifest } = def;
    mkdirSync(join(root, 'packs', id), { recursive: true });
    writeFileSync(
      join(root, 'packs', id, 'pack.mjs'),
      `export default ${JSON.stringify({ id, detect: null, worldRules: [], ruleRoutingGuidance: { belongs: `whatever ${id} owns`, excludes: `whatever ${id} does not own` }, ...manifest })};\n`
    );
    for (const name of skills) {
      mkdirSync(join(root, 'packs', id, 'skills', name), { recursive: true });
      writeFileSync(join(root, 'packs', id, 'skills', name, 'SKILL.md'), `---\nname: ${name}\n---\nbody\n`);
    }
  }
  return root;
}

function mount(corpus, project) {
  const r = spawnSync('node', [join(corpus, 'engine', 'pack_loader', 'mount-skills.mjs')], {
    encoding: 'utf8',
    env: { ...process.env, CLAUDE_PROJECT_DIR: project },
  });
  assert.equal(r.status, 0, r.stderr);
