python3 - <<'PY'
p='updates/install.mjs'
s=open(p).read()
s=s.replace("""  const next = JSON.parse(readFileSync(settingsFile, 'utf8'));
  // The newly-declared entries first, so every id this run stamps has an entry to
  // carry its version — `withInstalledVersions` drops a version for a pack the
  // declaration does not name, which is what keeps a stray stamp from activating
  // a pack nobody declared.
  next.packs = declared;""",
"""  const next = JSON.parse(readFileSync(settingsFile, 'utf8'));
  // THE RESOLVED ENTRIES, not the bare `declared` list: every pack this run stamps
  // needs an entry to carry its version, and a pack pulled in through another's
  // `requires` is installed exactly as much as a named one. That is not a
  // declaration made on the repo's behalf — `via` is what says so, written by
  // `resolveDeclaredPacks` and read by anything that must tell a chosen pack from an
  // inferred one. It is also what `--init` already seeds, so the two writers agree.
  //
  // Before #1252 the closure's versions lived in a central map that needed no entry,
  // which is why the two could disagree at all: a pack could be installed, stamped,
  // and named nowhere in the file it was stamped in.
  next.packs = entries;""")
open(p,'w').write(s)

p='engine-tests/install.test.mjs'
s=open(p).read()
s=s.replace("""  // …and the closure is INSTALLED, not DECLARED: what a repo declares is its own
  // choice, and `requires` is the canon's inference from it.
  assert.deepEqual(settingsOf(root).packs, ['basics'], 'a pulled-in pack is not a declaration the repo made');""",
"""  // …and a pulled-in pack is still not a CHOICE the repo made: it carries `via`,
  // naming the pack that pulled it in, which is how everything downstream tells an
  // inferred entry from a chosen one. It has an entry at all because that is where
  // its version lives now (#1252) — and because being unversioned was the exact hole
  // this test was written to close.
  const packs = settingsOf(root).packs;
  assert.deepEqual(packs.filter((e) => typeof e === 'string' || !e.via).map((e) => e.id ?? e), ['basics'],
    'only the named pack is a declaration the repo made');
  for (const id of pulled) {
    const entry = packs.find((e) => e?.id === id);
    assert.ok(entry?.via?.length, `${id} was pulled in but records no provenance`);
  }""")
open(p,'w').write(s)
